function kinetic(m,v){ return 0.5*m*v*v; }
function gpe(m,g,h){ return m*g*h; }
function elasticPE(k,x){ return 0.5*k*x*x; }
function springForce(k,x){ return -k*x; }
function work(F,d,thetaDeg){ var th=(thetaDeg==null?0:thetaDeg)*Math.PI/180; return F*d*Math.cos(th); }
function powerP(W,t){ return W/t; }
var EXPORTS={ kinetic:kinetic, gpe:gpe, elasticPE:elasticPE, springForce:springForce, work:work, powerP:powerP };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.EnergyForgePure = EXPORTS; }
